import manifest from './images.generated.json';

/** Generated by `npm run images` from scripts/images/sources.json. */
export type ImageKey = keyof typeof manifest;

export interface ImageCredit {
  title: string;
  creator: string;
  license: string;
  licenseUrl: string;
  page: string;
  via: string;
}

export interface ImageAsset {
  width: number;
  height: number;
  /** Available widths, smallest first. Files live at /images/<key>-<width>.avif|webp */
  widths: number[];
  alt: string;
  credit: ImageCredit;
}

export const images: Record<ImageKey, ImageAsset> = manifest;

/** Portrait composition of an image, when one exists (e.g. walk-3 -> walk-3-tall). */
export function tallVersion(key: ImageKey): ImageKey | undefined {
  const tall = `${key}-tall`;
  return tall in images ? (tall as ImageKey) : undefined;
}
